<script setup lang="ts">
import {t as tr} from "../../i18n";
import {useNativeCard} from '../../business/controller';
const {leftoverDescription,leftoverDeadline,leftoverIssue,business,result,readonly,context,note,shiftId,finalize,createIssue,receiverId,checklist,busy,admin,ownShifts,currentRecord,labels,checkText,period,dirty,prepare,inspect}=useNativeCard();
</script>
<template>
   <div v-if="result.view==='duty'">
    <p>{{tr("当前班次：")}}{{tr(context?.dutyGroups?.current.map(s=>s.roomName+' '+period(s.periodKey)).join('、')||'当前无本人班次')}} {{tr("· 下一班次：")}}{{tr(context?.dutyGroups?.next[0]?context.dutyGroups.next[0].date+' '+context.dutyGroups.next[0].roomName+' '+period(context.dutyGroups.next[0].periodKey):'未排班')}}</p>
    <p v-if="!ownShifts.length">{{tr("没有本人正式排班，不能从历史签到推测班次。")}}</p>
    <form v-if="ownShifts.length&&!readonly" class="native-form" @submit.prevent="inspect">
     <label class="wide">{{tr("本人班次")}}<select :aria-label="tr('本人班次')" v-model="shiftId" required><option v-for="s in ownShifts" :key="s.id" :value="s.id">{{tr(context?.dutyGroups?.current.some(x=>x.id===s.id)?'当前':context?.dutyGroups?.next.some(x=>x.id===s.id)?'后续':'历史')}} · {{s.date}} · {{s.roomName}} · {{period(s.periodKey)}}</option></select></label>
     <p v-if="currentRecord" class="wide">{{labels[currentRecord.status]||currentRecord.status}}</p>
     <label v-for="c in checklist" :key="c.key">{{c.label}}<select v-model="c.state" :aria-label="c.label" @change="dirty"><option value="unchecked">{{tr("未检查 / 未确认")}}</option><option value="done">{{tr("本人确认完成")}}</option><option value="abnormal">{{tr("发现异常")}}</option></select></label>
     <label class="wide">{{tr("事实与遗留事项")}}<textarea :aria-label="tr('事实与遗留事项')" v-model="note" required rows="2" @input="dirty"></textarea></label>
     <label class="wide">{{tr("新增结构化遗留事项（可留空）")}}<textarea :aria-label="tr('新增遗留事项')" v-model="leftoverDescription" rows="2" @input="dirty"></textarea></label><label>{{tr("遗留期限")}}<input :aria-label="tr('遗留期限')" type="date" v-model="leftoverDeadline" @input="dirty"></label><label>{{tr("关联已有工单")}}<select :aria-label="tr('遗留关联工单')" v-model="leftoverIssue" @change="dirty"><option value="">{{tr("不关联")}}</option><option v-for="i in context?.issues.filter(i=>i.roomId===ownShifts.find(s=>s.id===shiftId)?.roomId)||[]" :key="i.id" :value="i.id">{{i.description}} · {{i.id}}</option></select></label>
     <label class="check"><input v-model="createIssue" type="checkbox" @change="dirty">{{tr("异常关联工单")}}</label><label class="check"><input v-model="finalize" type="checkbox" @change="dirty">{{tr("提交最终交接（待他人接收）")}}</label>
     <label class="wide">{{tr("交接接收人")}}<select :aria-label="tr('交接接收人')" v-model="receiverId" @change="dirty"><option value="">{{tr("由管理员接收")}}</option><option v-for="u in context?.receivers||[]" :key="u.username" :value="u.username">{{u.username}}</option></select></label>
     <button :disabled="busy||ownShifts.find(s=>s.id===shiftId)?.date!==context?.date||['completed','awaiting_acceptance'].includes(currentRecord?.status||'')">{{tr("准备")}}{{tr(finalize?'最终交接':'检查登记 / 补全')}}</button>
    </form>
    <p class="native-card__source">{{tr("检查来自用户声明；照片、现场复核与签到签退分别记录。工单创建不会自动修复异常。")}}</p>
    <div v-for="h in context?.handovers||[]" :key="h.id" class="object-row"><b>{{h.id}} · {{tr(h.status==='awaiting_acceptance'?'交接待接收':labels[h.status]||h.status)}} · v{{h.revision}}</b><p>{{h.note}} {{tr("· 关联工单")}} {{tr(h.linkedIssueIds?.join('、')||'无')}}</p><details><summary>{{tr("检查修订历史")}}</summary><p v-for="r in h.revisions||[]" :key="r.revision">v{{r.revision}} · {{r.submittedAt}} · {{r.note}} · {{checkText(r.checklist)}}</p></details><button v-if="h.status==='awaiting_acceptance'&&h.actorId!==business.profile?.username&&!readonly&&(admin||h.receiverId===business.profile?.username)" :disabled="busy" @click="prepare({kind:'duty.accept',recordId:h.id,expectedRevision:h.revision,note:'本人已核对交接与遗留事项，确认接收',adoptItemIds:(context?.handoverItems||[]).filter(i=>i.recordId===h.id&&i.state!=='completed'&&(!i.assigneeId||i.assigneeId===h.actorId)).map(i=>i.id)})">{{tr("准备接收此交接")}}</button><button v-if="admin&&h.status==='awaiting_acceptance'&&!readonly" :disabled="busy" @click="prepare({kind:'duty.reassign',recordId:h.id,expectedRevision:h.revision,receiverId,note:'管理员核对接收账号后重新指定'})">{{tr("按当前接收人选择准备重新指定")}}</button></div>
    <article v-for="i in context?.handoverItems||[]" :key="i.id" class="object-row"><b>{{tr("遗留事项 ·")}} {{tr(i.state==='completed'?'已完成':'未完成')}} · v{{i.revision}}</b><p>{{i.description}} {{tr("· 负责人")}} {{i.assigneeId}} {{tr("· 期限")}} {{tr(i.deadline||'未指定')}} {{tr("· 来源")}} {{i.sourceShiftId}}</p><p>{{i.id}} {{tr("· 关联工单")}} {{tr(i.linkedIssueId||'无')}} {{tr("· 接续班次")}} {{tr(i.linkedShiftIds.join('、')||'未关联')}}</p><template v-if="!readonly&&i.state!=='completed'&&(admin||i.assigneeId===business.profile?.username)"><button :disabled="busy" @click="prepare({kind:'duty.item',itemId:i.id,expectedRevision:i.revision,action:'complete',note:'本人核对事实后登记此遗留事项完成'})">{{tr("准备标记事项完成")}}</button><button v-if="context?.dutyGroups?.nextShiftId" :disabled="busy" @click="prepare({kind:'duty.item',itemId:i.id,expectedRevision:i.revision,action:'carry',targetShiftId:context.dutyGroups.nextShiftId,note:'将未完成事项关联本人下一正式班次，检查状态重新逐项声明'})">{{tr("准备接续到本人下一班次")}}</button></template><details><summary>{{tr("事项流转历史")}}</summary><p v-for="(h,n) in i.history" :key="n">{{h.at}} · {{h.actorId}} · {{h.action}} · {{h.note}}</p></details></article>
   </div>
</template>
